import React from 'react';
import clsx from 'clsx';
import { motion } from 'framer-motion';
import './AcidScrollList.css';

export interface AcidScrollListItem {
    id: string;
    content: React.ReactNode;
    title?: string;
    timestamp?: string;
}

export interface AcidScrollListProps {
    items: AcidScrollListItem[];
    maxHeight?: string | number;
    className?: string;
}

export const AcidScrollList = ({
    items,
    maxHeight = '400px',
    className
}: AcidScrollListProps) => {
    return (
        <div
            className={clsx('ac-scroll-list-container', className)}
            style={{ maxHeight }}
        >
            <div className="ac-scroll-list-mask ac-mask-top" />
            <div className="ac-scroll-list-viewport">
                {items.map((item, index) => (
                    <motion.div
                        key={item.id}
                        initial={{ opacity: 0, x: -10 }}
                        whileInView={{ opacity: 1, x: 0 }}
                        viewport={{ once: true }}
                        transition={{ delay: index * 0.05 }}
                        className="ac-scroll-item"
                    >
                        <div className="ac-scroll-item-indicator" />
                        <div className="ac-scroll-item-content">
                            {item.title && (
                                <div className="ac-scroll-item-header">
                                    <span className="ac-scroll-item-title">{item.title}</span>
                                    {item.timestamp && <span className="ac-scroll-item-time">{item.timestamp}</span>}
                                </div>
                            )}
                            <div className="ac-scroll-item-body">
                                {item.content}
                            </div>
                        </div>
                    </motion.div>
                ))}
            </div>
            <div className="ac-scroll-list-mask ac-mask-bottom" />
        </div>
    );
};

.ac-scroll-list-container {
    position: relative;
    border: 1px solid var(--ac-border-muted);
    border-radius: 8px;
    background: var(--ac-bg);
    overflow: hidden;
}

.ac-scroll-list-viewport {
    height: 100%;
    overflow-y: auto;
    padding: 1.5rem 1rem;
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.ac-scroll-list-viewport::-webkit-scrollbar {
    width: 4px;
}

.ac-scroll-list-viewport::-webkit-scrollbar-track {
    background: transparent;
}

.ac-scroll-list-viewport::-webkit-scrollbar-thumb {
    background: var(--ac-border-muted);
    border-radius: 4px;
}

.ac-scroll-list-viewport::-webkit-scrollbar-thumb:hover {
    background: var(--ac-brand);
}

.ac-scroll-list-mask {
    position: absolute;
    left: 0;
    right: 0;
    height: 40px;
    pointer-events: none;
    z-index: 2;
}

.ac-mask-top {
    top: 0;
    background: linear-gradient(to bottom, var(--ac-bg), transparent);
}

.ac-mask-bottom {
    bottom: 0;
    background: linear-gradient(to top, var(--ac-bg), transparent);
}

.ac-scroll-item {
    display: flex;
    gap: 12px;
    position: relative;
    padding-bottom: 1rem;
    border-bottom: 1px solid rgba(255, 255, 255, 0.03);
}

.ac-scroll-item:last-child {
    border-bottom: none;
    padding-bottom: 0;
}

.ac-scroll-item-indicator {
    width: 2px;
    background: var(--ac-border-muted);
    position: relative;
}

.ac-scroll-item:hover .ac-scroll-item-indicator {
    background: var(--ac-brand);
}

.ac-scroll-item-content {
    flex: 1;
    min-width: 0;
}

.ac-scroll-item-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 4px;
}

.ac-scroll-item-title {
    font-size: 0.7rem;
    font-weight: 700;
    color: var(--ac-text-primary);
    font-family: var(--font-mono);
    text-transform: uppercase;
}

.ac-scroll-item-time {
    font-size: 0.6rem;
    color: var(--ac-text-muted);
    font-family: var(--font-mono);
}

.ac-scroll-item-body {
    font-size: 0.75rem;
    color: var(--ac-text-secondary);
    line-height: 1.4;
}
